// Generated from n8n-resume-processor/lib. Edit the lib, then run scripts/build-workflow.mjs.
function assertObject(raw) {
  if (raw == null || typeof raw !== 'object' || Array.isArray(raw)) {
    throw new Error('Config must be a JSON object with the keys from config.example.json.');
  }
}

function readKeys(raw, keys, action) {
  assertObject(raw);
  const value = {};
  const missing = [];
  for (const key of keys) {
    const current = raw[key];
    if (typeof current !== 'string') {
      missing.push(key);
      continue;
    }
    const next = current.trim();
    if (!next || next.startsWith('PASTE_')) missing.push(key);
    else value[key] = next;
  }
  if (missing.length) {
    throw new Error(`Config is incomplete. ${action} Missing or placeholder: ${missing.join(', ')}.`);
  }
  return value;
}

function assertFolderId(key, value) {
  if (/^https?:\/\//i.test(value) || value.includes('/folders/')) {
    throw new Error(
      `${key} must be the Drive folder id, not the full URL. Copy the id after /folders/ in the address bar.`,
    );
  }
  if (/[\s'"]/.test(value)) {
    throw new Error(`${key} must be a Drive folder id with no spaces or quotes.`);
  }
}

function driveQuery(folderId) {
  const escaped = folderId.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
  return `'${escaped}' in parents and mimeType = 'application/pdf' and trashed = false`;
}

function checkConfig(raw) {
  const value = readKeys(
    raw,
    ['client_id', 'client_secret', 'refresh_token', 'folder_in', 'folder_out'],
    'Fill config.json and run node n8n-resume-processor/scripts/apply-config.mjs, or paste the five values into the Config node.',
  );
  assertFolderId('folder_in', value.folder_in);
  assertFolderId('folder_out', value.folder_out);
  return {
    ...value,
    drive_query: driveQuery(value.folder_in),
  };
}

const checked = checkConfig($input.first().json);
return [{ json: checked }];

// Generated from n8n-resume-processor/lib. Edit the lib, then run scripts/build-workflow.mjs.
function collectFiles(pages) {
  const files = [];
  for (const page of pages) {
    const list = page && Array.isArray(page.files) ? page.files : [];
    for (const file of list) {
      if (!file || typeof file.id !== 'string' || !file.id.trim()) continue;
      if (file.mimeType !== 'application/pdf') continue;
      files.push({
        id: file.id.trim(),
        name: typeof file.name === 'string' && file.name.trim() ? file.name.trim() : `${file.id.trim()}.pdf`,
        mimeType: 'application/pdf',
      });
    }
  }

  const seen = new Set();
  const unique = [];
  for (const file of files) {
    if (seen.has(file.id)) continue;
    seen.add(file.id);
    unique.push(file);
  }
  unique.sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base', numeric: true }));
  return { files: unique, count: unique.length };
}

const pages = $input.all().map((item) => item.json);
const collected = collectFiles(pages);
return [{ json: collected }];

