// Generated from n8n-resume-processor/lib. Edit the lib, then run scripts/build-workflow.mjs.
function buildMultipart({ text, folderOut, boundary }) {
  if (typeof folderOut !== 'string' || !folderOut.trim()) {
    throw new Error('Config folder_out is empty. Set the Google Drive output folder id.');
  }
  if (typeof text !== 'string') {
    throw new Error('Resume report text is missing.');
  }
  if (text.includes(boundary)) {
    throw new Error('The resume report contains the multipart boundary, so the upload body would be invalid.');
  }
  const metadata = JSON.stringify({
    name: 'result.txt',
    parents: [folderOut.trim()],
    mimeType: 'text/plain',
  });
  const payload =
    `--${boundary}\r\n` +
    'Content-Type: application/json; charset=UTF-8\r\n\r\n' +
    `${metadata}\r\n` +
    `--${boundary}\r\n` +
    'Content-Type: text/plain; charset=UTF-8\r\n\r\n' +
    `${text}\r\n` +
    `--${boundary}--\r\n`;
  return {
    payload,
    fileName: 'result.txt',
    contentType: `multipart/related; boundary=${boundary}`,
  };
}

function readReportText(readNode) {
  const names = ['Aggregate Output', 'Empty Result'];
  for (const name of names) {
    try {
      const output = readNode(name);
      if (typeof output === 'string') return output;
    } catch {
      // The other branch did not run.
    }
  }
  throw new Error('No aggregated resume text was produced.');
}

const text = readReportText((nodeName) => $(nodeName).first().json.output);
const folderOut = $('Check Config').first().json.folder_out;
const built = buildMultipart({
  text,
  folderOut,
  boundary: 'n8n_resume_boundary_7f3a9c',
});
const binary = await this.helpers.prepareBinaryData(
  Buffer.from(built.payload, 'utf8'),
  built.fileName,
  built.contentType,
);
return [{
  json: {
    fileName: built.fileName,
    contentType: built.contentType,
    bytes: Buffer.byteLength(built.payload, 'utf8'),
  },
  binary: { data: binary },
}];
